12	/// The free–free adjacency of a model's structural pattern.
13	pub fn free_adjacency(model: &Model) -> Vec<Vec<usize>> {
14	    let n = model.nodes.len() * 6;
15	    let mut restrained = vec![false; n];
16	    for &(node, c) in &model.constraints {
17	        restrained[node as usize * 6 + c] = true;
18	    }
19	    let mut position = vec![usize::MAX; n];
20	    let mut count = 0;
21	    for g in 0..n {
22	        if !restrained[g] {
23	            position[g] = count;
24	            count += 1;
25	        }
26	    }
27	    let mut sets: Vec<BTreeSet<usize>> = vec![BTreeSet::new(); count];
28	    let mut couple = |dofs: &[usize]| {
29	        for &a in dofs {
30	            for &b in dofs {
31	                if a != b && position[a] != usize::MAX && position[b] != usize::MAX {
32	                    sets[position[a]].insert(position[b]);
33	                }
34	            }
35	        }
36	    };
37	    for m in &model.members {
38	        let dofs: Vec<usize> = [m.node_i, m.node_j]
39	            .iter()
40	            .flat_map(|&k| (0..6).map(move |c| k as usize * 6 + c))
41	            .collect();
42	        couple(&dofs);
43	    }
44	    for s in &model.springs {
45	        if s.axis.is_none() {
46	            let off = if s.translation { 0 } else { 3 };
47	            let dofs: Vec<usize> = (0..3).map(|c| s.node as usize * 6 + off + c).collect();
48	            couple(&dofs);
49	        }
50	    }
51	    sets.into_iter().map(|s| s.into_iter().collect()).collect()
52	}
