54	/// K4's and SD's orders on one adjacency (valid input only).
55	pub fn both_orders(adjacency: &[Vec<usize>]) -> (Vec<usize>, Vec<usize>) {
56	    (
57	        k4_rcm(adjacency),
58	        sd_rcm(adjacency).expect("valid adjacency"),
59	    )
60	}
